'use strict';
// themes/*.json and preview.html are generated by `blogctl zen` from ZEN.md. The colour-role
// mapping is crates/blog-site/src/zen/theme.json; preview.template.html in this folder is the
// page template it fills. This script only checks that the generated files are current.
const { checkZen } = require('../../research-blog/scripts/zen-check.cjs');

try {
  checkZen();
  console.log('Graphite、Paper 两套主题和 preview.html 与 ZEN.md 一致。');
} catch (error) {
  console.error(error.message);
  process.exitCode = 1;
}
